BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (409::BIGINT, 'No sabe redactar en lo más mínimo. Pero fuera de eso, atiende consultas en la clase y explica de manera clara, ya que la idea es hacer ejercicios. Los videos son consisos y van directo al grano. No revisa ni un solo correo, así que aproveche para hacer todas las consultas que pueda en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '12dd3e0e549b3a65a751e944d6a8fc150f7407946556c21f92ac2c2e6c676323'::TEXT, ARRAY[1316]::BIGINT[]),
    (409::BIGINT, 'Pésimo, pésimo, totalmente pésimo. Repite en clases sincrónicas lo mismo que están en los videos que deja asincrónicos, entonces se vuelven inútiles las clases. Hizo el examen para la casa y una semana después dijo que lo hizo mal y tuvo que volver a mandarlo. Es muy desordenado.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-11-03T00:00:00+00:00'::TIMESTAMPTZ, '9197f40ac99494722ccef5d2b0068f81d7c0fa12d3e3b49e9604ecd14b77ae85'::TEXT, ARRAY[1316]::BIGINT[]),
    (409::BIGINT, 'Este semestre se portó mejor y en realidad no estuvo tan mal. La primera mitad del curso la da Adolfo y en realidad es sencilla ya que la materia no es difícil y el examen es a libro abierto, pero el problema es la tarea que es muy pesada'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2025-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'acad0e7ee964f3badfb12adaf55f0d7f520fed5136a2eaf90a3a7bb5229aff7c'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Su forma de explicar no es clara. Esto es, se pone a decir una misma cosa una y otra vez sin llegar a nada (esto es su explicación). A menudo contesta de forma grosera si le escribes en privado. La tarea que asignó no se podía resolver con el libro. Sus clases grabadas me ayudaron con la tarea.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-02-22T00:00:00+00:00'::TIMESTAMPTZ, 'e4f40c81ef50747b97e67926d4904cdef7702324846f4f2fc65eafbf40a4ee9d'::TEXT, ARRAY[1316]::BIGINT[]),
    (409::BIGINT, 'Como dicen por ahí, piensa que todos los estudiantes lo quieren engañar. Se la pasa tirando indirectas de que no lo van a tomar del pelo, por esta razón parece algo rudo al hablar sobre las evaluaciones. Si le pregunta algo puede que su respuesta sea "eso ya lo vimos en clases" o "eso es de análisis'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, '0c7cc8c91ede74e4688ba487808f7fd179792c72d4d94d2cdac7bb6a7db001e2'::TEXT, ARRAY[1316]::BIGINT[]),
    (409::BIGINT, 'Sabe de lo que esta hablando y explica bien, sin embargo tiene problemas de actitud, es muy prepotente, no se le puede contradecir con aspectos como las rubricas o otros aspectos de asignaciones por que el "siempre" tiene la razón y vive pensado que todos los estudiantes lo quieren engañar.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-12-09T00:00:00+00:00'::TIMESTAMPTZ, '732cfcb88110f86cddd16101fb845897ded788c784cc45e9e6b719953c56e271'::TEXT, ARRAY[1316]::BIGINT[]),
    (409::BIGINT, 'Cerrado en sus propias opiniones, con problemas de carácter, y se pone dema poco en los zapatos del estudiante. Sin embargo conoce mejor la materia que los otros dos profes que dieron el curso este semestre.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-07T00:00:00+00:00'::TIMESTAMPTZ, '9d74a4964ac5897f62de5bbbfd132462c7cc7e8805840412f6579916c40c0cd9'::TEXT, ARRAY[1316]::BIGINT[]),
    (409::BIGINT, 'Tiene un caracter algo particular, pero en general este semestre se portó muy bien , respondía a dudas con gusto y le gusta mucho la materia que da y se nota, sin embargo si hay que pulirse en las tareas, si sales mejor en la 2nda tarea , es la misma nota para las 2, examen a libro abierto'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '7fedc316910ad990a908a8a99fa2fb29d66db99cbcd57c915fd7d41b3c79fc9a'::TEXT, ARRAY[1316]::BIGINT[]),
    (409::BIGINT, 'El mae sabe mucho de control, pero de impartir clases no, es un pedante y se confunde mucho explicando, si usted le pregunta algo puede que termine humillado. Los exámenes son sencillos y a libro abierto. Lo complicado es la tarea ya que es muy estricto calificándola.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '3dd55f666dfbc1a6b63e77b46ac55eb28f4036e0ea1a1cd553fe9f5ee78f7da2'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Profe exageradamente malo para dar clases, el curso es bonito y sencillo pero este profesor es demasiado malo, que espacio ni qué nada, de los peores profesores que he tenido.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-08T00:00:00+00:00'::TIMESTAMPTZ, '8aab1e0a860ae2565ef42a1ba9600fddd4d731958923b2e7745101eedbd289bd'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Muy buen profesor a pesar de los comentarios pasados. Hace el curso muy interesante y de verdad le interesa mucho la materia y que el estudiante aprenda. Dio muchas oportunidades para mejorar la nota y para evacuar dudas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-24T00:00:00+00:00'::TIMESTAMPTZ, '689a465fdee83af1a3b861b0f419a1bc48170d8eef5bd769db5ec4e6dee92a9e'::TEXT, ARRAY[1316]::BIGINT[]),
    (409::BIGINT, 'La materia del curso no es tan dificil pero el profe complica el curso más de lo necesario con la bendita tarea. Haga la tarea porque tiene mucho peso y si puede proponga un sistema desde el inicio.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-09T00:00:00+00:00'::TIMESTAMPTZ, '54d2b240743feba270aa09a88b45e9dad30659364f80d68b0298e4dc34e634a3'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Ego por las nubes, calidad por el suelo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-27T00:00:00+00:00'::TIMESTAMPTZ, 'bd768cadfdd8f7af6a7478796d146bd6e96b319ec88166c464f77629a17bfb65'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'La materia y las clases son fáciles, aunque la explicación de la materia puede llegar a ser confusa, la tarea es muy pesada, es lo más difícil de este curso, hay que ponerle y se pasa fácil'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'f51defbf0e6126c631aac252889af3233e68960a2a4d3f0975d328b2b71b9b2a'::TEXT, ARRAY[1305, 1316]::BIGINT[]),
    (409::BIGINT, 'El curso es muy suave en realidad, pero el profe no es como el mejorexplicando aunque intente hacerse el buena nota. La ayuda (sobre todo en las tareas) es minima. Esa tarea es lo mas dificil del curso, una tarea sumamente larga y complicada'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '54c393f47d947722ec8fd7ccb1a6643beea8fbb7eac499a63d921184b6d00f26'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Malo , el profe "intenta" ser buena nota , pero no lo logra. Las clases que enviaba en videos, algunas tenían error y no eran de la mejor calidad los videos. La tarea es muy pesada y ayuda muy poco, por no decir que nunca ayuda. Lo unico bueno es que la materia y examenes son fáciles'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '73cf5eec4f69e56b597ac4b89a911ee71444860657d99571eee0ef1bc6c0d3a1'::TEXT, ARRAY[1305, 1316]::BIGINT[]),
    (409::BIGINT, 'si ese es nuestro futuro espacial...no llevó madre'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-03T00:00:00+00:00'::TIMESTAMPTZ, '6839e59ffed7f1c4d370a2eb6710d1544657fa67fe048ac8dfa8aaecc2d1f78b'::TEXT, ARRAY[3064]::BIGINT[]),
    (409::BIGINT, 'La teoría la da toda en videos de un semestre anterior y hay algunos que no están muy bien, con errores o no se escuchan bien, sin embargo se aprende mucho. La tarea es una trabajo muy grande así que es bueno conseguir un buen grupo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '977bc87ac1a57909e16c2f96921a0a627a547e36b9563399c1670a115043f63c'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'De forma virtual es muy fácil pasar el curso, en los vídeos que deja explica bien la materia y en las clases sincrónicas hace bastantes ejercicios. El profe es buena gente y para las tareas da retroalimentación, los exámenes no son tan difíciles. Lo único malo es que tarda mucho en dar notas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '62c85f747704ca868a49220268e45a1bd94912af95d6b90539d1889450ea4c45'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Es una basura de profe, no responde consulta, cualquier cuestionamiento se pone a la defensiva e intenta variar la evaluación como le da la gana.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b49c258f31f612dbd3e7a09cc3cff414a4901b768cf402aad8db83eb185fe917'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'El mae se equivoca en el 80% de los ejercicios y siempre pone excusas, es pésimo profesor'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-02T00:00:00+00:00'::TIMESTAMPTZ, '565ae1646400a6054bc7ec68f6606b1ac9842876d536fdc2beeb49be864e1d7a'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Al profe se le da bastante bien dar clases mediante los videos que hace, se le entiende bien. Deja dos tareas que al final se hace como una sola y los exámenes no son tan difíciles, bastante recomendado para la modalidad virtual.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'ad453f2b08c1bd62eb57aefde4b9071717648e67452d7a9405feef9f06cd64b5'::TEXT, ARRAY[3064]::BIGINT[]),
    (409::BIGINT, 'Este curso es super interesante, puesto que es el fuerte del profe lo explica con mucho cariño y se le nota las ganas de dar el curso. Es la mejor electiva de Electro.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '805585110c4654e9ecfeb4f46d8ac1028f7dee13d13d5a87eb757d7ff34b161d'::TEXT, ARRAY[1349]::BIGINT[]),
    (409::BIGINT, 'El profe ayudó bastante en consultas, tenía buena disponibilidad. Los exámenes son fáciles, las 2 tareas son como un proyecto (le recomiendo que escojan su propio sistema para trabajarlas, no usen el que da el profe). Califica bien, es pura vida. Clases por videos de youtube'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'bd8080d2625d08145b5fdcfdac0046d6fffb2815269a0a2c7c15b5ad3cf0c138'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'El curso fue súper fácil, los exámenes también fueron fáciles y el profe explica súper bien. También hace muchos ejercicios de práctica'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '88369804d16eed773b51ea3c21c32adcf00f1cf341c043570a147c2696acf15b'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Muy buen profe, evaluaciones relativamente sencillas y enfocadas al verdadero aprendizaje. Explica muy bien aunque es bastante enredado pero con gracia. El único problema es, que después de la noticia de que VA AL ESPACIO (crack), se desapareció un poco por la mitad del curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'e9bd70a090c245ba7cf23b7e2188a1c96173c88101b4f859ad08721ad97a993e'::TEXT, ARRAY[3064]::BIGINT[]),
    (409::BIGINT, 'Son dos examenes bastantes encillos. En el segundo dio una práctica de examen con el mismo formato del examen y si se había estudiado bien para la práctica el examen era super sencillo. Los libros son un buen apoyo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '68ca2e6745247ae18f99a3fca48a21d3c99345d47bd32bf27107b259990ffce0'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'El curso en modalidad virtual fue muy sencillo, dos exámenes muy fáciles y dos tareas que quitan algo de tiempo, pero que califica muy suave. Siento que no aprendí mucho en el curso, pero prácticamente es el único profe que lo imparte.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '129c7ab61357f28f237f904be7231ec082f5a127089f3622cb7dc8755be7507a'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Las evaluaciones son secillas y las explicaciones son suficientes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '4da71cdda43a4438820d2f0813a33c069451a1846eec60907855756adb5650ee'::TEXT, ARRAY[3064]::BIGINT[]),
    (409::BIGINT, 'Es medio camote y dura mucho entregando notas. A veces es mejor no preguntarle nada porque termina cagandolo todo. Pero casi que es el único profe que da el curso.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-12-27T00:00:00+00:00'::TIMESTAMPTZ, 'd9ee1bd67a967de227ec4c70d3a4bf4d905522abf8724c053cfb16a6e501ce93'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Este mae está camote'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '9fddf62b00318bd080c85e23ff5a7cd3a90bd5d1fb871cc0d859c7efef4229d2'::TEXT, ARRAY[1305, 1316]::BIGINT[]),
    (409::BIGINT, 'Entregó la nota del examen muy tarde y no brindó la solución del mismo, es difícil que de consulta fuera del horario, en veces no responde los correos y si da consulta en realidad no aclara mucho las dudas, el examen estuvo bien, acorde a la materia.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'c7af2527f7d641494021441dcfda2e9571e2769edf0a1248646dc8570b8eeabf'::TEXT, ARRAY[1349]::BIGINT[]),
    (409::BIGINT, 'Dos tareas y dos exámenes como evaluación y es flexible al evaluar. El examen es más sencillo que la tarea, así que se puede utilizar la tarea como práctica. Suele responder rápido las consultas durante el semestre, excepto al final.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '0fd7f2a8c8a588cb303ebdb02c0171cb49785a05bebe6e1d32f7904888fb8380'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Es el peor profesor que he tenido en la U, un profesor que se cree que lo sabe todo, exige demasiado pero cuando uno lo busca para preguntarle algo, no aparece o si aparece, no le ayuda a uno en nada. Super irresponsable, califica las evaluaciones super tarde'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, '457e211cb165038bec6b896dccc17c690bf06feda361f39cd4d1e4a86f347df5'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Solo hizo 2 exámenes y 2 tareas que juntas son como un proyecto de simulación. El curso no estuvo muy pesado, el profe explica bien, se nota que sabe y sabe expresarlo. El primer examen fue hacer 3 problemas de cálculos a mano y el segundo examen se hizo en Google forms. Bastante fáciles ambos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'd7d58ade6952cea3b31776492d1d71dea1447969a3d5109d865a0559d35a1226'::TEXT, ARRAY[3064]::BIGINT[]),
    (409::BIGINT, 'No lo recomiendo para nada, super bipolar, casi no ayuda y cuesta que responda dudas importantes. No explica muchas cosas y luego asume que si las dijo en clase, le interesa más aspectos superficiales en los trabajos que los aspectos técnicos. Facil pasar pero no vale la pena aguantarselo. Evitelo.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'ebe8b75053636b7f0b3df85ba9ac3436e2235a0990b463dfd8529d304cd85526'::TEXT, ARRAY[1349]::BIGINT[]),
    (409::BIGINT, 'bipolar, no prepara clase, no sabe absolutamente nada'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'a09052a9cc721243cb4235e5c62766248353272b57edc97bcd875d75e2207928'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Con él me di cuenta que cualquiera puede ser "profesor". Es de lo peor en la escuela. Solo le importan sus satélites y cohetes inútiles. Es raro y estoy seguro que tiene problemas psicológicos. Nunca está en consulta y es de esos mediocres que cree que si más de media clase se queda es algo bueno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-28T00:00:00+00:00'::TIMESTAMPTZ, 'c37f7d5a2fe74f37eecff4b1ae2c2723142ee1af475ed96586be7f369e28f362'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Evitarlo es la mejor decisión, este profesor tiene serios problemas de bipolaridad, es extraño y hace comentarios sumamente extraños. También es abusivo al dirigirse a los demás, cortesía y comunicación 0, yo tengo una presencia fuerte y nunca me deje y me respeto pero al final el pone notas y cedí.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '1e57b76c59b064b5a6824ec7d2d94e0dbb985f8863e524b61f5ff248da11a1d5'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'El peor profesor de electro que he tenido, asigna tareas complicadas para la calidad de clases que brinda. Se pone de mal humor si las personas van a consulta (si lo encuentra porque prefiere salir de la oficina en tiempo de consulta por lo que casi nunca está), califica examenes sin criterio.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, '0d3ecbf46bf3b5a70c8566a4c4fa766c80c490ab14ae18ffe3ce526a929230f5'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Malo, se pasa enredando en clase, en clase no se puede ni susurrar porque el mae se pone en varas, dura una vida entregando las tareas y los exámenes. Realmente no lo recomiendo, la clase es una pérdida de tiempo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'ef0879afebee07e8bfaeed60366f99c81e849d024c18650339591c487ccae0e1'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Se enreda un poco, califica regular peeo da bastantes ejemplos en clase, tutorías, explica bastante y atiende muy bien las dudas de los estudiantes. Se realizan dos tarea grandes que se se hacen se aprende mucho y no se necesita casi ni estudiar. Es fácil pasar con él y con una buenoa nota.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, '746355a1d734017376d5e78fcf47889178f9a00047a976c257f4172f7fbfd50e'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Me preocupa que alguien que se nota que es mentalmente inestable siga dando clases y no busque ayuda. Tiene un ego gigante.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd9e6bf490ecb1d83ef324aab29126bacae43aedf4109eee32630959b8337a99b'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'El mae explica bastante bien, hace ejemplos representativos de la materia, lo único pesado del curso es la tarea final que es un poco laboriosa. En general se aprende bastante, es una buena opción'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '97ef1e6e2e2a0e56b89c2ed6b4c40414407cb54c68f9da3c12155ae71740b860'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Buen profe, comprensivo con el tiempo con el que cuentan los estudiantes, domina la materia por lo que si se le pregunta si es de ayuda'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '82ef62b6e3cd88f03f48745c1be00da56a74e3ddcea4a46f38feeb4a1106ef3e'::TEXT, ARRAY[1321]::BIGINT[]),
    (409::BIGINT, 'No da clases y no domina la materia, basicamene se roba el salario, si mete con el sepa que no tiene profesor. Si muestra un poco de conocimiento en el examen el mae lo pasa.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-13T00:00:00+00:00'::TIMESTAMPTZ, '5e7bf79bc211bce8b1a8b6152a9f0dc58492fb6588b4ca1e24d5e1e8702a0509'::TEXT, ARRAY[3556, 1297, 1386]::BIGINT[]),
    (409::BIGINT, 'Una lástima que para un curso tan importante, solo haya un inútil como él dandolo. El curso se pasa fácil, pero si quiere aprender algo del curso haga la tarea a consciencia'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'bb22b74b0be6c08ef40637c8ba2b95f5900d238653218489a7b7d7099e592743'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'El peor profesor que he tenido en el TEC. Es el peor de electrónica y posiblemente el peor de toda la universidad. Pasa viajando y cancelando clases, las clases que da son inútiles, prácticamente no da consulta y como persona es un desgraciado juega de vivo. Pedante, odioso y un asco de "profesor".'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '5160b76520268afa4a188ab5adbfd1438b248ef5529e3334791d8ee7ed37a221'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'Pésimo profesor, pasa en otros países por su proyecto del satélite, y le importa un carajo si da la materia. Como los exámenes son colegiados igual entra todo a uno, aunque el no haya visto la materia. Entonces no (por nada en el mundo) meta Modelos con el'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '8d976e8adb61fdacb21f32ecf4bbd0e53f6327a3b04722119b8f241f24050670'::TEXT, ARRAY[1296]::BIGINT[]),
    (409::BIGINT, 'Yo pase, pero el profe es muy irresponsable, falta a clases y no las repone, no le importa con el estudiante, no le gusta da consulta ( hay que pedir cita previa) y cuando la da, es de 5 min , para una tarea que dejo tuve que ir a consulta con otros 4 profes por que el estaba fuera del país.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'b61867896abc14b61024dbe55e3a7ccee19e6b3558605c0e40e44db7f9877bf7'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'El peor profesor, ni Rivas es tan irresponsable. Las clases son inútiles, nunca da ejemplos, califica muy duro y NO da la talla. Este curso se pasa con los videos de Pablo, las prácticas de Barboza siendo COMPLETAMENTE autodidacta y esforzándose el triple.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Pocos exámenes']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'd72436f38469c5f3583038fc516bef7cb6356a388094d52711ab427265b1ac8f'::TEXT, ARRAY[1296]::BIGINT[]),
    (409::BIGINT, 'Mal profe. Expone el libro en clase. Muy militar en las evaluaciones (te regaña hasta por respirar), califica rudísimo y se enoja por cualquier cosa.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '268fdfcaf2c4bde53fdf610fbc58799ef55dd482492215da019b3b8208716b44'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'No entiendo, como alguien que fue dotado con solo 1 neurona es profesor del TEC. Y no es ofensa, es una realidad siempre se equivoca, anda perdido con la materia, pone excusas para todo...'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '57502973c9ec9e8339fd00357268eb2742f6d5115b0dbe3c8bace9ae98af8e99'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'El peor profe que he tenido. De verdad nunca matriculen con él. Nunca da clases, y cuando las da sólo lee las presentaciones, y tras de todo califica muy binario. De verdad EVITENLO'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-10T00:00:00+00:00'::TIMESTAMPTZ, '732bacec27e2a86c4852d496c11a82b7bbaedca6555d301fb36e93ec5f94c4a9'::TEXT, ARRAY[1296]::BIGINT[]),
    (409::BIGINT, '"Simple y llanamente" no sé cómo es "profesor", sólo va a leer las diapositivas de las presentaciones de Barboza, eso cuando da la clase, porque se pierden demasiadas clases (pasa viajando fuera del país). Si matriculan con él, es mejor que vayan de oyentes con otro profe.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, '962162945bd72905b5ec3671683729e8aff5662f2c9f8557854e8c4a28d5af2b'::TEXT, ARRAY[1296]::BIGINT[]),
    (409::BIGINT, 'La clase es tan monótona y unidireccional que no se puede aprender nada. En los exámenes revisa respuesta y califica como una bestia. Por amor de Dios, no matriculen con Adolfo. Pero sí recomiendo leer el libro o ir de oyente antes de llevar el curso porque es duro'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4d8dce46d971aa63ec0f8ec3beea6335dbe54cbff10f3d811730a16468f30a06'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'El profesor en sí da todo los temas, pero no tan bien. Cuando pida realimentacion ponga lo que ud quiere como profe, no se quede callado. Ayuda bastante. Es muy disperso y se confunde mucho en clase. Haga las tareas a conciencia y le va ir excelente.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '31035e6ab1385f1caf87e5a172272c124e8ba60d827e8ca6c5a15626f3030776'::TEXT, ARRAY[1305]::BIGINT[]),
    (409::BIGINT, 'No lo haga compa'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'c277369b32681f265a127fc9e909da07aeb6354ce3e1a8dba3257d65045e1c99'::TEXT, ARRAY[1316, 3544, 3560]::BIGINT[]),
    (409::BIGINT, 'Este Mae no sabe un carajo de control, no se como ponen a estos maes a dar clases'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-08-10T00:00:00+00:00'::TIMESTAMPTZ, '3c2b468bb586ada0ff73be0bee255de88b4c79b81aba6bb8105a6d3ddce1be2e'::TEXT, ARRAY[1316, 3544, 3560]::BIGINT[]),
    (409::BIGINT, 'No lo recomiendo, no explica nada bien. Quién dijo que tiene doctorado?, no lo ha terminado de sacar.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'a312587b999af27832a78edad364bb1cc9fc6d10952eb18c2065a2339bb5c7ff'::TEXT, ARRAY[1316]::BIGINT[]),
    (409::BIGINT, 'Pésimo, el mae podrá tener un doctorado pero NO SABE NADA...'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '963bfddcd5e4b32427aae4904e824fa030af177f95590953ab711e89d7d826c8'::TEXT, ARRAY[1316, 3544, 3560]::BIGINT[]),
    (409::BIGINT, 'El problema con Adolfo es que no es bueno explicando la materia, lo intenta pero mas bien termina confundiendo al estudiante.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2017-05-02T00:00:00+00:00'::TIMESTAMPTZ, '5a47bfa106911ade5085937f277f2337cc590b9ec7ef0ae27bc62428fd48a8e5'::TEXT, ARRAY[1316]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
